const body = $input.first().json.body;

const from = body.From || '';
const messageBody = body.Body || '';
const accountSid = body.AccountSid || '';
const to = body.To || '';

if (!from || !messageBody) {
  throw new Error('Missing required Twilio fields: From or Body');
}

return [{
  json: {
    from,
    messageBody,
    accountSid,
    to
  }
}];

const response = $input.first().json;

let replyMessage = '';
let actionData = null;
let action = 'none';

// Check if Claude API call was successful
if (response.error || !response.content) {
  replyMessage = '¡Hola! En este momento tengo un problemita técnico 😅 Por favor escríbenos de nuevo en unos minuticos o llámanos directamente. ¡Disculpa las molestias!';
  return [{
    json: {
      replyMessage,
      actionData: null,
      action: 'none',
      from: $('Extract Twilio Fields').item.json.from,
      to: $('Extract Twilio Fields').item.json.to,
      apiError: true
    }
  }];
}

// Extract text from Claude response
const content = response.content;
if (Array.isArray(content) && content.length > 0) {
  replyMessage = content[0].text || '';
} else {
  replyMessage = '';
}

// Detect ACTION_DATA in the response
const actionMatch = replyMessage.match(/ACTION_DATA:(\{[^\n]+\})/);
if (actionMatch) {
  try {
    actionData = JSON.parse(actionMatch[1]);
    action = actionData.action || 'none';
    // Remove ACTION_DATA line from the reply sent to customer
    replyMessage = replyMessage.replace(/\nACTION_DATA:\{[^\n]+\}/, '').replace(/ACTION_DATA:\{[^\n]+\}/, '').trim();
  } catch (e) {
    actionData = null;
    action = 'none';
  }
}

// Parse date DD/MM/YYYY to ISO for Google Calendar
function parseToISO(dateStr, timeStr) {
  if (!dateStr) return null;
  const parts = dateStr.split('/');
  if (parts.length !== 3) return null;
  const day = parts[0].padStart(2, '0');
  const month = parts[1].padStart(2, '0');
  const year = parts[2];
  const time = timeStr || '10:00';
  return `${year}-${month}-${day}T${time}:00-05:00`;
}

function parseEndISO(dateStr, timeStr) {
  if (!dateStr) return null;
  const parts = dateStr.split('/');
  if (parts.length !== 3) return null;
  const day = parts[0].padStart(2, '0');
  const month = parts[1].padStart(2, '0');
  const year = parts[2];
  const timeParts = (timeStr || '10:00').split(':');
  let hours = parseInt(timeParts[0]);
  const mins = timeParts[1] || '00';
  hours = hours + 1;
  return `${year}-${month}-${day}T${String(hours).padStart(2,'0')}:${mins}:00-05:00`;
}

let calendarPayload = {};
if (actionData) {
  if (action === 'agendar') {
    calendarPayload = {
      summary: `💈 ${actionData.servicio} - ${actionData.nombre}`,
      description: `Cita en Barbería Élite\nCliente: ${actionData.nombre}\nServicio: ${actionData.servicio}\nWhatsApp: ${$('Extract Twilio Fields').item.json.from}`,
      location: 'Calle 10 #43-15, El Poblado, Medellín, Antioquia',
      start: { dateTime: parseToISO(actionData.fecha, actionData.hora), timeZone: 'America/Bogota' },
      end: { dateTime: parseEndISO(actionData.fecha, actionData.hora), timeZone: 'America/Bogota' },
      colorId: '9'
    };
  } else if (action === 'cancelar') {
    calendarPayload = {
      searchSummary: `${actionData.nombre}`,
      searchDate: parseToISO(actionData.fecha, '00:00')
    };
  } else if (action === 'modificar') {
    calendarPayload = {
      searchSummary: `${actionData.nombre}`,
      searchDate: parseToISO(actionData.fecha_actual, '00:00'),
      newStart: { dateTime: parseToISO(actionData.nueva_fecha, actionData.nueva_hora), timeZone: 'America/Bogota' },
      newEnd: { dateTime: parseEndISO(actionData.nueva_fecha, actionData.nueva_hora), timeZone: 'America/Bogota' },
      newSummary: `💈 ${actionData.nuevo_servicio} - ${actionData.nombre}`
    };
  }
}

return [{
  json: {
    replyMessage,
    actionData,
    action,
    calendarPayload,
    from: $('Extract Twilio Fields').item.json.from,
    to: $('Extract Twilio Fields').item.json.to,
    apiError: false
  }
}];

// Error handler: forward fallback message downstream
const parsed = $('Parse Claude Response').item.json;
return [{ json: parsed }];
